import random

def mapv(v, ol, oh, nl, nh):
    """maps the value `v` from old range [ol, oh] to new range [nl, nh]
    """
    return nl + (v * ((nh - nl) / (oh - ol)))

def terrain_naive(count) -> List[float]:
    """returns the list of integers representing height at each point.
    """
    return [
        mapv(random.random(), 0, 1, 0, 100)
        for i in range(count)
    ]

def execution_levels(graph: dict[str, list[str]]) -> list[list[str]]:
    in_degree = defaultdict(int)
    for node in graph:
        for dep in graph[node]:
            in_degree[dep] += 1

    levels = []
    ready = [n for n in graph if in_degree[n] == 0]

    while ready:
        levels.append(ready)
        next_ready = []
        for node in ready:
            for dep in graph[node]:
                in_degree[dep] -= 1
                if in_degree[dep] == 0:
                    next_ready.append(dep)
        ready = next_ready

    return levels

type BlockingQueue struct {  
    queue chan Task  
}

func NewBlockingQueue(capacity int) *BlockingQueue {  
    return &BlockingQueue{  
        queue: make(chan Task, capacity),  
    }  
}

// Producer goroutine  
func produce(bq *BlockingQueue) {  
    task := createTask()  
    bq.queue <- task  // Blocks if queue is full  
}

// Consumer goroutine  
func consume(bq *BlockingQueue) {  
    task := <-bq.queue  // Blocks if the queue is empty  
    processTask(task)  
}

func (bq *BlockingQueue) OfferWithTimeout(task Task, timeout time.Duration) bool {  
    select {  
    case bq.queue <- task:  
        return true  
    case <-time.After(timeout):  
        return false  
    }  
}

func (bq *BlockingQueue) PollWithTimeout(timeout time.Duration) (Task, bool) {  
    select {  
    case task := <-bq.queue:  
        return task, true  
    case <-time.After(timeout):  
        return Task{}, false  
    }  
}

func (bq *BlockingQueue) TryOffer(task Task) bool {  
    select {  
    case bq.queue <- task:  
        return true  
    default:  
        return false  
    }  
}

func (bq *BlockingQueue) TryPoll() (Task, bool) {  
    select {  
    case task := <-bq.queue:  
        return task, true  
    default:  
        return Task{}, false  
    }  
}

