func consumeBatch(queue chan Task) {  
    batch := make([]Task, 0, 100)  

    // Block for first item  
    task := <-queue  
    batch = append(batch, task)  

    // Drain additional available items without blocking  
    for len(batch) < 100 {  
        select {  
        case task := <-queue:  
            batch = append(batch, task)  
        default:  
            break  
        }  
    }  

    // Process entire batch  
    for _, t := range batch {  
        process(t)  
    }  
}

